def parse_jobs():
    reader = csv.DictReader(CSV_TEXT.strip().split('\n'))
    jobs = []
    for row in reader:
        jid = row['Job Number'].strip()
        if not jid:
            continue
        status_raw = (row['Status'] or 'Completed').strip()
        status = status_raw
        if status_raw == 'JobCompleted':
            status = 'Job completed'
        elif status_raw in ['OnGoing', 'Ongoing']:
            status = 'Ongoing'
        elif status_raw == 'Open':
            status = 'Open'
        elif status_raw == 'SES Submitted':
            status = 'Under SES approval'
        elif status_raw == 'DraftInvoiceSubmitted':
            status = 'Draft invoiced'
        elif status_raw == 'Completed':
            status = 'Completed'

        amount_str = (row['Invoiced Amount'] or '0').replace(',', '').replace('"', '').strip()
        try:
            inv_amt = float(amount_str) if amount_str else 0.0
        except:
            inv_amt = 0.0

        job = {
            'id': jid,
            'rig': (row['Rig'] or '').strip(),
            'well': (row['Well'] or '').strip(),
            'client': (row['Client'] or '').strip(),
            'contract': (row['Project Code'] or row['Client'] or '').strip(),
            'poNumber': (row['PO Number'] or '').strip(),
            'serviceType': (row['Job Description'] or 'Downhole Rental').strip(),
            'status': status,
            'mobDate': (row['Start Date'] or '').strip(),
            'demobDate': (row['End Date'] or '').strip(),
            'legalInvoiceNumber': (row['Legal Number'] or '').strip(),
            'draftInvoiceNumber': (row['Emdad Invoice No.'] or '').strip(),
            'invoiceAmount': inv_amt,
            'invoicingType': 'PerJob',
            'currency': 'USD',
            'createdBy': 'Operations',
            'createdDate': '2023-01-01',
        }
        jobs.append(job)

    print(f"Parsed {len(jobs)} initial jobs")
    with open('src/data/importedJobs.json', 'w') as f:
        json.dump(jobs, f, indent=2)

if __name__ == '__main__':
    parse_jobs()
